            .indent_level = 0,
            .pretty = pretty,
        };
    }

    pub fn deinit(self: *HtmlRenderer) void {
        self.buffer.deinit();
    }

    pub fn render(self: *HtmlRenderer, root: *const Node) ![]const u8 {
        const visitor = Visitor(HtmlRenderer){
            .enterFn = enterNode,
            .leaveFn = leaveNode,
        };
        visitor.walk(root, self);
        return self.buffer.items;
    }

